#include "PreRTS.h"
#include "GameLogic/Object.h"
#include "GameLogic/PartitionManager.h"

Bool PartitionFilterRejectByKindOf::allow(Object *objOther)
{
	const KindOfMaskType &mustBeSet = *(const KindOfMaskType *)((const char *)this + 0x08);
	const KindOfMaskType &mustBeClear = *(const KindOfMaskType *)((const char *)this + 0x20);
	return !objOther->isKindOfMulti(mustBeSet, mustBeClear);
}
